import { isCi } from "../env.js";
import { getAgentDisplayName, resolveAddMcpAgentId, uniqueAgentIds } from "../mcp/agents.js";
import prompts from "prompts";
//#region src/utils/agent_picker.ts
const canPickAgentsInteractively = () => !isCi() && Boolean(process.stdout.isTTY) && Boolean(process.stdin.isTTY);
const pickAgentsInteractively = async (options) => {
	if (!canPickAgentsInteractively()) throw new Error("No interactive terminal. Pass -y, or run this command in a terminal to pick agents.");
	if (options.choices.length === 0) throw new Error("No coding agents are available to pick.");
	const selected = new Set(options.selected ?? []);
	const { agents } = await prompts({
		onState: (state) => {
			if (state.aborted) {
				process.stdout.write("\x1B[?25h");
				process.stdout.write("\n");
				process.exit(1);
			}
		},
		type: "multiselect",
		name: "agents",
		message: options.message,
		instructions: false,
		min: 1,
		choices: options.choices.map((choice) => ({
			value: choice.id,
			title: choice.title,
			description: choice.description,
			selected: selected.has(choice.id)
		}))
	});
	if (!Array.isArray(agents)) throw new Error("Aborted: no agents selected.");
	const picked = [];
	for (const value of agents) {
		const id = agentIdInChoices(value, options.choices);
		if (id === void 0) throw new Error(`Unknown agent: "${String(value)}".`);
		picked.push(id);
	}
	return uniqueAgentIds(picked);
};
const resolveAgentSelection = async (options) => {
	if (options.specified.length > 0) {
		const resolve = options.resolveSpecified ?? resolveAddMcpAgentId;
		return uniqueAgentIds(options.specified.map(resolve));
	}
	const pick = options.pick ?? (options.interactive ?? canPickAgentsInteractively() ? pickAgentsInteractively : void 0);
	if (pick) {
		const selected = await pick({
			message: options.message,
			choices: options.choices,
			selected: options.detected.filter((id) => options.choices.some((choice) => choice.id === id))
		});
		if (selected.length === 0) throw new Error("No agents selected. Pick at least one agent, or pass -y to use detected agents.");
		return uniqueAgentIds(selected);
	}
	if (options.detected.length > 0) return uniqueAgentIds(options.detected);
	throw new Error(options.nonInteractiveMessage);
};
const agentChoicesFrom = (available, detected) => {
	const detectedSet = new Set(detected);
	return [...available.filter((id) => detectedSet.has(id)), ...available.filter((id) => !detectedSet.has(id))].map((id) => ({
		id,
		title: getAgentDisplayName(id),
		...detectedSet.has(id) ? { description: "detected" } : {}
	}));
};
const agentIdInChoices = (value, choices) => {
	if (typeof value !== "string") return;
	for (const choice of choices) if (choice.id === value) return choice.id;
};
//#endregion
export { agentChoicesFrom, canPickAgentsInteractively, pickAgentsInteractively, resolveAgentSelection };
